import groovy.json.JsonSlurper
import groovy.xml.XmlSlurper
import java.util.ArrayList
import java.time.LocalDate
import java.time.format.DateTimeFormatter

def checkParameter(String paramName, def expValue, def currentValue){
	if(currentValue != expValue){ 
		testRunner.fail()
		log.info("значение "+paramName+" не соответствует ожидаемому. ожидаемое ="+expValue.toString()+", фактическое ="+currentValue.toString())
	}
}

def getAssignmentsReferralsInfoResponse = context.expand('${getAssignmentsReferralsInfo#Response}')// вызываем метод, записывыем его ответ в виде текста в переменную
def slurperJson = new JsonSlurper()//штука для парсинка джейсона
def getAssignmentsReferralsInfo = slurperJson.parseText(getAssignmentsReferralsInfoResponse)//парсим текст и получаем объект в коде с которым можно работать

def getAssignmentsInfoSAOResponse = context.expand('${getAssignmentsInfo#Response}')
def slurperXml = new XmlSlurper()
getAssignmentsInfoSAO = slurperXml.parseText(getAssignmentsInfoSAOResponse)

def getReferralsInfoSAOResponse = context.expand('${getReferralsInfo#Response}')
getReferralsInfoSAO = slurperXml.parseText(getReferralsInfoSAOResponse)

def countInfo=getAssignmentsReferralsInfo.payload.arInfo.count
def assigmentsCount=getAssignmentsInfoSAO.Body.getAssignmentsInfoResponse.assignment.size()
def referralsCount=getReferralsInfoSAO.Body.getReferralsInfoResponse.referral.size()
def expectedCountSAO=assigmentsCount+referralsCount

log.info " getAssignmentsReferralsInfo вернул " + countInfo + " getAssignmentsInfo вернул " + assigmentsCount + " getReferralsInfo вернул " +  referralsCount + " ожидаемое значение " +  expectedCountSAO
checkParameter("AssignmentsReferralsCount",expectedCountSAO, countInfo)

import groovy.json.JsonSlurper
import groovy.xml.XmlSlurper
import java.util.ArrayList
import java.time.LocalDate
import java.time.format.DateTimeFormatter

def checkParameter(String paramName, def expValue, def currentValue){
	if(currentValue != expValue){ 
		testRunner.fail()
		log.info("значение "+paramName+" не соответствует ожидаемому. ожидаемое ="+expValue.toString()+", фактическое ="+currentValue.toString())
	}
}

def getAssignmentsReferralsInfoResponse = context.expand('${getAssignmentsReferralsInfo#Response}')
def slurperJson = new JsonSlurper()
def getAssignmentsReferralsInfo = slurperJson.parseText(getAssignmentsReferralsInfoResponse)
def getAssignmentsInfoSAOResponse = context.expand('${getAssignmentsInfo#Response}')
getAssignmentsInfoSAO = new XmlSlurper().parseText(getAssignmentsInfoSAOResponse)

def countInfo=getAssignmentsReferralsInfo.payload.arInfo.assignments.items.size()
def assigmentsCount=getAssignmentsInfoSAO.Body.getAssignmentsInfoResponse.assignment.size()

checkParameter("count", assigmentsCount, countInfo)

def assigmentsINFO=getAssignmentsReferralsInfo.payload.arInfo.assignments.items
def assigmentsSAO=getAssignmentsInfoSAO.Body.getAssignmentsInfoResponse.assignment

assigmentsSAO.sort {it.period.dateTo} // ментод принимает на вход лямбду в фигурных скобках. лябда - это функция которую можно передать в аргументы функции
// в данной ситуации в лямбде  передается функция которая указывает как происходит сортировка по какому полю так можно сказать
// it это над кем вызывается функция. В данной ситуации у нас массив ассайментов и вот эта функция вызывается над каждым асайментом и в итоге сортирует массв


for (int i=1; i<assigmentsINFO.size(); i++){
	if(assigmentsINFO[i-1].period.dateTo> assigmentsINFO[i].period.dateTo){
		testRunner.fail(" не отсортированы по дате окончания ")
	}
}

checkParameter("sizeAssigments", assigmentsINFO.size(),assigmentsSAO.size())

for (int i=0; i<assigmentsINFO.size(); i++){
	def assigmentSAO=assigmentsSAO[i]// текущий ассаймент из хмл всевсе все взяли из хмл (что внутри ассаймента)
	def assigmentINFO=assigmentsINFO[i]// текущий ассайент из джейсона
	def appointmentIdINFO=assigmentINFO.appointmentId? assigmentINFO.appointmentId : null// тернаный оператор. если assigmentINFO.appointmentId не нулл то берем  assigmentINFO.appointmentId иначеnull 
	def appointmentIdSAO=assigmentSAO.appointmentId? assigmentSAO.appointmentId.toLong() : null// здест  тернарный оператор действительно имеет смысл потому что надо вызвать тулонг только есть поле не нулл

	checkParameter("moid", assigmentSAO.moId.toLong(), assigmentINFO.moId)
	checkParameter("toBM.id", assigmentSAO.toBM.id.toLong(), assigmentINFO.toBM.id)
	checkParameter("toBM.name", assigmentSAO.toBM.name.toString(), assigmentINFO.toBM.name)
	checkParameter("toBM.self", assigmentSAO.toBM.self.toBoolean(), assigmentINFO.toBM.self)
	checkParameter("appointmentId", appointmentIdSAO, appointmentIdINFO)
	checkParameter("appointmentId", appointmentIdSAO, appointmentIdINFO)
	log.info assigmentSAO.period.dateFrom.toString() +   assigmentINFO.period.dateFrom
	checkParameter("period.dateFrom", assigmentSAO.period.dateFrom.toString(),  assigmentINFO.period.dateFrom)
	checkParameter("period.dateTo", assigmentSAO.period.dateTo.toString(),  assigmentINFO.period.dateTo)
	checkParameter("active", assigmentSAO.active.toBoolean(), assigmentINFO.active)
	checkParameter("appointmentAvailable", assigmentSAO.appointmentAvailable.toBoolean(), assigmentINFO.appointmentAvailable)


	def registryEntriesINFO=assigmentINFO.registryEntry
	def registryEntriesSAO=assigmentSAO.registryEntry

	checkParameter("sizeRegistryEntries", registryEntriesSAO.size(),  registryEntriesINFO.size())

	for (int m=0; m<registryEntriesSAO.size(); m++){
		def registryEntryINFO=registryEntriesINFO[m]
		def registryEntrySAO=registryEntriesSAO[m]
		//log.info " жду " + registryEntrySAO.entryId.toLong()+ " получаю "  + registryEntryINFO.entryId
		checkParameter("entryId", registryEntrySAO.entryId.toLong(), registryEntryINFO.entryId)
		checkParameter("laboratoryId", registryEntrySAO.laboratoryId.toLong(), registryEntryINFO.laboratoryId)
		checkParameter("laboratoryName", registryEntrySAO.laboratoryName.toString(), registryEntryINFO.laboratoryName)
		checkParameter("biomaterialId", registryEntrySAO.biomaterialId.toLong(), registryEntryINFO.biomaterialId)
		checkParameter("biomaterialName", registryEntrySAO.biomaterialName.toString(), registryEntryINFO.biomaterialName)
		checkParameter("hasMemo", registryEntrySAO.hasMemo.toBoolean(), registryEntryINFO.hasMemo)
	}


}

import groovy.json.JsonSlurper import groovy.xml.XmlSlurper import java.util.ArrayList import java.time.LocalDate import java.time.format.DateTimeFormatter
DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd");
def getAssignmentsReferralsInfoResponse = context.expand('${getAssignmentsReferralsInfo#Response}') def slurperJson = new JsonSlurper() def getAssignmentsReferralsInfo = slurperJson.parseText(getAssignmentsReferralsInfoResponse) def getReferralsInfoSAOResponse = context.expand('${getReferralsInfo#Response}') getReferralsInfoSAO = new XmlSlurper().parseText(getReferralsInfoSAOResponse) def countInfo=getAssignmentsReferralsInfo.payload.arInfo.referrals.items.size() def referralsCount=getReferralsInfoSAO.Body.getReferralsInfoResponse.referral.size()
assert countInfo==referralsCount
def referralsINFO=getAssignmentsReferralsInfo.payload.arInfo.referrals.items def referralsSAO=getReferralsInfoSAO.Body.getReferralsInfoResponse.referral
referralsSAO.sort {it.endTime} newSAO=[] referralsSAO.each{ sao -> dateString=sao.endTime.toString() LocalDate newDate = LocalDate.parse(dateString, formatter) map=[id:sao.id.toLong(),endTime:newDate] newSAO << map }
for (int i=1; i<countInfo; i++){ if(referralsINFO[i-1].endTime> referralsINFO[i].endTime){ testRunner.fail(" не отсортированы по датеокончания ") } }
newSAO.sort {it.endTime} newSAO.each{ log.info "newSAO "+it }
for (int i=0; i<countInfo; i++){ log.info "зашли в цикл "+i referralSAO=[] for (int k=0; k<countInfo;k++){ log.info "сравниваю referralsINFO "+i+" "+referralsINFO[i].id+" и referralsSAO "+k+" "+referralsSAO[k].id if(referralsINFO[i].id.toLong()==referralsSAO[k].id.toLong()){ referralSAO=referralsSAO[k] break }
} referralINFO=referralsINFO[i] invalidINFO=referralINFO.invalid? referralINFO.invalid : null invalidSAO=referralSAO.invalid? referralSAO.invalid.toLong() : null commentINFO=referralINFO.comment ? referralINFO.comment : null commentSAO=referralSAO.comment.toString() !='' ? referralSAO.comment.toString() : null lpuIdINFO=referralINFO.lpuId ? referralINFO.lpuId : null lpuIdSAO=referralSAO.lpuId ? referralSAO.lpuId.toLong() : null lpuNameINFO=referralINFO.lpuName ? referralINFO.lpuName : null lpuNameSAO=referralSAO.lpuName.toString() !='' ? referralSAO.lpuName.toString() : null availableResourceIdINFO=referralINFO.availableResourceId ? referralINFO.availableResourceId : null availableResourceIdSAO=referralSAO.availableResourceId ? referralSAO.availableResourceId.toLong() : null log.info i log.info "referralINFO "+ referralINFO.id log.info "referralSAO "+referralSAO.id assert referralINFO.id.toLong()==referralSAO.id.toLong() assert invalidINFO==invalidSAO assert referralINFO.startTime==referralSAO.startTime.toString() assert referralINFO.endTime==referralSAO.endTime.toString() assert referralINFO.type==referralSAO.type.toString() assert lpuIdINFO==lpuIdSAO assert lpuNameINFO==lpuNameSAO assert availableResourceIdINFO==availableResourceIdSAO assert referralINFO.countActiveAppointment.toLong()==referralSAO.countActiveAppointment.toLong() assert referralINFO.countAppointmentWithReceptionFact.toLong()==referralSAO.countAppointmentWithReceptionFact.toLong()
if(referralINFO.type=='REF_TO_DOCTOR'){ toDoctorINFO=referralINFO.toDoctor toDoctorSAO=referralSAO.toDoctor doctorFioNameINFO=referralINFO.doctorFioName ? referralINFO.doctorFioName : null doctorFioNameSAO=referralSAO.doctorFioName.toString() !='' ? referralSAO.doctorFioName.toString() : null assert toDoctorINFO.specialityId== toDoctorSAO.specialityId.toLong() assert toDoctorINFO.specialityName== toDoctorSAO.specialityName.toString() assert toDoctorINFO.receptionTypeId== toDoctorSAO.receptionTypeId.toLong() assert doctorFioNameINFO == doctorFioNameSAO }
if(referralINFO.type=='REF_TO_LDP'){ toLdpINFO=referralINFO.toLdp toLdpSAO=referralSAO.toLdp countAssignmentProceduresINFO=referralINFO.countAssignmentProcedures ? referralINFO.countAssignmentProcedures : null countAssignmentProceduresSAO=referralSAO.countAssignmentProcedures.toString() !='' ? referralSAO.countAssignmentProcedures.toString() : null assert toLdpINFO.ldpTypeId== toLdpSAO.ldpTypeId.toLong() assert toLdpINFO.ldpTypeName== toLdpSAO.ldpTypeName.toString() assert countAssignmentProceduresINFO == countAssignmentProceduresSAO } log.info "успешно проверено направление №"+ referralINFO.id }
log.info "end."
